    .reg .b32    %rIdx, %rBlk, %rThd, %rBDim, %rGrid, %rStride, %rNum, %rN4, %rV, %rI, %rBase;
    .reg .b64    %in, %out, %addr_in, %addr_out, %off, %mask, %tmp64;
    .reg .f32    %x, %negx, %t, %e, %den, %y, %log2e;
    .reg .f32    %x0, %x1, %x2, %x3, %y0, %y1, %y2, %y3;
    // Load parameters
    ld.param.u64 %in,  [in_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.u32 %rNum, [numel];
    // Convert to global space (generic -> global)
    cvta.to.global.u64 %in,  %in;
    cvta.to.global.u64 %out, %out;
    // Compute thread index and stride
    mov.u32 %rThd,  %tid.x;
    mov.u32 %rBlk,  %ctaid.x;
    mov.u32 %rBDim, %ntid.x;
    mad.lo.u32 %rIdx, %rBlk, %rBDim, %rThd;   // idx = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %rGrid, %nctaid.x;                // gridDim.x
    mul.lo.u32 %rStride, %rBDim, %rGrid;      // stride = blockDim.x * gridDim.x
    // Constant log2(e) for exp path
    mov.f32 %log2e, 1.44269502;
    // Number of vec4 elements
    shr.u32 %rN4, %rNum, 2;
    // Alignment check for vectorized path (16-byte aligned)
    mov.u64 %mask, 15;
    and.b64 %tmp64, %in, %mask;
    setp.eq.u64 %p_in_al, %tmp64, 0;
    and.b64 %tmp64, %out, %mask;
    setp.eq.u64 %p_out_al, %tmp64, 0;
    and.pred %p_align, %p_in_al, %p_out_al;
    setp.ne.u32 %p_hasv, %rN4, 0;
    and.pred %p_vec, %p_align, %p_hasv;
    @!%p_vec bra SCALAR_ALL;
    // Vectorized main loop (v4)
    mov.u32 %rV, %rIdx;
