    setp.ge.u32 %p_done, %rV, %rN4;
    @%p_done bra TAIL_VEC;
    // off = rV * 16 bytes
    mul.wide.u32 %off, %rV, 16;
    add.s64 %addr_in, %in, %off;
    add.s64 %addr_out, %out, %off;
    // Load 4 floats
    ld.global.v4.f32 {%x0, %x1, %x2, %x3}, [%addr_in];
    // Sigmoid via exp approximation: y = 1 / (1 + exp(-x))
    // x0
    neg.f32 %t, %x0;
    mul.f32 %t, %t, %log2e;
    ex2.approx.f32 %e, %t;
    add.f32 %den, %e, 1.0;
    rcp.approx.f32 %y0, %den;
    // x1
    neg.f32 %t, %x1;
    mul.f32 %t, %t, %log2e;
    ex2.approx.f32 %e, %t;
    add.f32 %den, %e, 1.0;
    rcp.approx.f32 %y1, %den;
    // x2
    neg.f32 %t, %x2;
    mul.f32 %t, %t, %log2e;
    ex2.approx.f32 %e, %t;
    add.f32 %den, %e, 1.0;
    rcp.approx.f32 %y2, %den;
    // x3
    neg.f32 %t, %x3;
    mul.f32 %t, %t, %log2e;
    ex2.approx.f32 %e, %t;
    add.f32 %den, %e, 1.0;
    rcp.approx.f32 %y3, %den;
    // Store 4 floats
